function active$Form&Controller;(f) {
  f.add_onResponseComplete(on$Form&Controller;$ResponseComplete);
  var g = f.grid, info = g._$dataGL, client = info.Client;
  setValueField$ByArrayValue(f, info, client[info.IndexActive]);
  f._$fieldType = getFieldByType(f._fields, 'list');
  onChange$Voucher&Controller;$DepreciationMethodSelectedIndex(f.getItem('kieu_kh'));
}
function close$Form&Controller;(f) {
  try {f.remove_onResponseComplete(on$Form&Controller;$ResponseComplete)} catch (ex) {}
  window.setTimeout(function() {var g = f.grid;if (g._activeCell) g._activeCell.focus();else {var t1 = g._$parentForm._findButton('Ok');if (t1) {t1.focus();t1.live;}}}, 50);
}

function on$Form&Controller;$ResponseComplete(sender, e) {
  var f = e.object, context = e.type.Context, result = e.type.Result, g = f.grid;
  switch (context) {
    case 'Checking':
      objectBehavior$Dir$Irregular.checkCode(f, 'so_the_ts');\
      if !(f._checked) {break;}

      var info = g._$dataGL, client = info.Client;
      var value = getValueField$ByFields(f, info);
      var row = g._activeRow;
      info.Client[info.IndexActive] = value;
      g._setItemValue(row, g._getColumnOrder('so_the_ts'), f.getItemValue('so_the_ts').toUpperCase());
      g._setItemValue(row, g._getColumnOrder('ten_ts'), f.getItemValue('ten_ts'));
      f._checked = false;
      f.closeDialog();
      break;
    case 'FACategoryCreateAuto':
      f.setItemControlBehavior('kieu_kh', result[0].Value, null, true);
      f.setItemValue('so_ky_kh', result[1].Value);
      f.setItemValue('tl_kh00', result[2].Value);
      f.setItemValue('ma_phi', result[3].Value);
      f.setItemControlBehavior('loai_ts', result[4].Value, result[5].Value, true);
      f.setItemControlBehavior('ma_tg_ts', result[6].Value, result[7].Value, true);
      f.setItemControlBehavior('tk_ts', result[8].Value, result[9].Value, true);
      f.setItemControlBehavior('tk_kh', result[10].Value, result[11].Value, true);
      f.setItemControlBehavior('ma_nv', result[12].Value, result[13].Value, true);

      onChange$Voucher&Controller;$DepreciationMethodSelectedIndex(f.getItem('kieu_kh'));
      onChange$&Controller;$DepreciationPeriods(f.getItem('so_ky_kh'));
      break;
    default:
      break;
  }
}

function onChange$&Controller;$OriginalCostFC(o) {
  var f = o.parentForm;
  f.executeExpression(['[gt_cl_nt]:=[nguyen_gia_nt]']);
  f.executeExpression(['[gt_kh_ky_nt]:=[so_ky_kh] == 0 ? 0 : [nguyen_gia_nt]/[so_ky_kh]']);
}
function onChange$&Controller;$OriginalCost(o) {
  var f = o.parentForm;
  f.executeExpression(['[gt_cl]:=[nguyen_gia]']);
  f.executeExpression(['[gt_kh_ky]:=[so_ky_kh] == 0 ? 0 : [nguyen_gia]/[so_ky_kh]']);
}
function onChange$&Controller;$FACategoryCreateAuto(o) {o.parentForm.request('FACategoryCreateAuto', 'FACategoryCreateAuto', ['ma_pl_ts'], o);}
function onChange&Controller;$Currency(f) {
  var v = (f._baseCurrency&Controller;.toUpperCase() == f.getItemValue('ma_nt').toUpperCase());
  var a = ['nguyen_gia', 'nguyen_gia_nt'];
  var b = a[0].split(','), c = a[1].split(',');
  for (var i = 0; i < b.length; i++) {
    var n1 = $func.trim(b[i]), n2 = $func.trim(c[i]);
    var c1 = $get('idf_' + n1), c2 = $get('idf_' + n2), t1 = f.getItem(n1), t2 = f.getItem(n2);
    var format, h = t2._controlBehavior, changed = v;

    if (v) {
      if (!t2._saveDataFormatString) t2._saveDataFormatString = t2.field.DataFormatString;
      format = t1.field.DataFormatString;
    else {
      format = t2.field.DataFormatString;
      changed = true;
    }
    if (changed) {
      t2.field.DataFormatString = format;
      h.set_format(format);
      var n = $func.scaleLength(format);
      h._set_number($func.round(h._get_number(), n));
      $common.setVisible(t1.parentNode, !v);
    }
  }
}

function getFieldByType(a, resultMode) {
  var result = {DateTime: [], Upper: []};
  for (var i = 0; i < a.length; i++) {
    var item = a[i], name = item.Name, type = item.Type;
    switch (type) {
      case 'DateTime':
        result.DateTime.push(name);
        break;
      case 'String':
        var style = item.ItemStyle, format = item.DataFormatString;
        if (style == 'AutoComplete' || (style == 'Mask' && format == 'X')) {result.Upper.push(name);}
        break;
      default:
        break;
    }
  }
  return (resultMode == 'list' ? result : {DateTime: result.DateTime.join(), Upper: result.Upper.join()});
}

function onChange$&Controller;$DepreciationStartDate(o) {
  var f = o.parentForm, d = f.getItem('ngay_kh_kt');
  if (f.getItemValue('so_ky_kh') != 0) increaseDays$AutoGenerate(f.$_method&Controller;, f.getItemValue('ngay_kh0'), f.getItemValue('so_ky_kh'), d);
    else f.setItemValue('ngay_kh_kt', null);
}

function onChange$&Controller;$DepreciationPeriods(o) {
  var f = o.parentForm, d = f.getItem('ngay_kh_kt');
  f.executeExpression(['[gt_kh_ky_nt]:=[so_ky_kh] == 0 ? 0 : [nguyen_gia_nt]/[so_ky_kh]']);
  f.executeExpression(['[gt_kh_ky]:=[so_ky_kh] == 0 ? 0 : [nguyen_gia]/[so_ky_kh]']);
  f.executeExpression(['[gt_cl_nt]:=[nguyen_gia_nt]']);
  f.executeExpression(['[gt_cl]:=[nguyen_gia]']);

  if (o.value != 0) increaseDays$AutoGenerate(f.$_method&Controller;, f.getItemValue('ngay_kh0'), f.getItemValue('so_ky_kh'), d);
    else f.setItemValue('ngay_kh_kt', null);
}

function onChange$Voucher&Controller;$DepreciationMethodSelectedIndex(o) {
  var f = o.parentForm, c = o.value, v = (c != 2);
  f.getItem('tl_kh00').disabled = v;
}

      &ScriptIrregular;
